<a href="/growth">← All personal goals</a><header class="page-header asset-heading"><div><p class="eyebrow"><?= e(GrowthService::CATEGORIES[$goal['category']]) ?> · <?= e($goal['status']) ?></p><h1><?= e($goal['title']) ?></h1><p class="muted"><?= e($goal['notes']) ?></p></div></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<?php $done=count(array_filter($steps,fn($s)=>$s['status']==='done')); $pct=$goal['status']==='done' ? 100 : ($steps ? (int)round($done/count($steps)*100) : 0); ?><section class="card"><h2>Your progress</h2><?= progress_donut((float)$pct,'Step completion',$done.' of '.count($steps).' steps complete') ?><p class="footnote"><?= !$steps ? 'No steps yet. Break this goal into something you can do next.' : 'Complete prerequisites before their dependent steps. Finish every step before marking the goal done.' ?></p></section>
<div class="two-col"><section class="card"><h2>Steps & milestones</h2><?php if (!$steps): ?><p class="muted">No data yet. Add your first actionable step.</p><?php else: foreach ($steps as $s): ?><article class="lesson-entry"><div class="section-heading"><div><strong><?= e($s['title']) ?></strong><small><?= $s['is_milestone'] ? 'Milestone · ' : '' ?><?= e($s['status']) ?><?= $s['due_date'] ? ' · Due '.e($s['due_date']) : '' ?></small></div><?php if ($goal['status']!=='done'): ?><form action="/growth/<?= e($goal['id']) ?>/steps/<?= e($s['id']) ?>/status" method="post"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $s['status']==='done' ? 'open' : 'done' ?>"><button class="secondary"><?= $s['status']==='done' ? 'Reopen' : 'Complete' ?></button></form><?php endif; ?></div><?php if ($s['prerequisite']): ?><p class="muted">Prerequisite: <?= e($s['prerequisite']) ?> · <?= e($s['prerequisite_status']) ?></p><?php endif; ?><?php if ($goal['status']!=='done'): ?><details><summary>Edit step</summary><?php $step=$s; require __DIR__.'/step-form.php'; unset($step); ?></details><form action="/growth/<?= e($goal['id']) ?>/steps/<?= e($s['id']) ?>/delete" method="post" data-confirm="Delete this step? Dependent steps will no longer require it."><?= csrf_field() ?><button class="delete">Delete step</button></form><?php endif; ?></article><?php endforeach; endif; ?><?php if ($goal['status']!=='done'): ?><h3>Add a step</h3><?php require __DIR__.'/step-form.php'; endif; ?></section><section class="card"><h2>Edit goal</h2><?php require __DIR__.'/goal-form.php'; ?><form method="post" action="/growth/<?= e($goal['id']) ?>/delete" data-confirm="Delete this goal and all its steps? Dependent goals will no longer require it."><?= csrf_field() ?><button class="delete">Delete goal</button></form></section></div>
